head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
    var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
    var r = d(id); if (r) return r;
    var s = dd(P + id); r = d(s); if (r) return r;
    var g = s.indexOf('G_');
    if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
    return d(s.replace(P, ''));
};
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    requires("uiplugin.popup"); //팝업을 사용하기 위해 반드시 포함되어야 한다.
    //dataList1.getRowJSON와 같은 API 호출 시 반환 객체.
    var rowJSON = {
        "addr": "서울시",
        "name": "손예진",
        "rowStatus": "R"
    };
    //popup에 넘길 data객체.
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array"
        data: rowJSON, // 전달 데이터 객체.
        name: "rowObj" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다.
    };
    var options = {
        id: "popup1",
        type: "window",
        width: "230px",
        height: "250px",
        top: "130px",
        left: "200px",
        popupName: "openPopup1",
        modal: true,
        useIFrame: true,
        frameMode: 'wframe',
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: false,
        useModalStack: true,
        alwaysOnTop: true,
        dataObject: dataObj
    };
    $w.openPopup("popup_wframe_onpageload_WPFF-80_(WSQ-3230)_sub.xml", options);
};
scwin.checkElement = function(id) {
    if (scwin.__getDom(id)) {
        return true;
    }
    return false
}
scwin.checkVal = function() {
    return window.log == true;
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 22-Feb-2018
}
